import StarterKit from "@tiptap/starter-kit";
import type {
  SuggestionKeyDownProps,
  SuggestionProps,
} from "@tiptap/suggestion";
import type { ChatStatus } from "ai";
import {
  ArrowUpIcon,
  AtSignIcon,
  Loader2Icon,
  SquareIcon,
  XIcon,
} from "lucide-react";
import {
  type ComponentProps,
  createContext,
